// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title IoTDeviceRegistry - Manages firmware update tokens for IoT devices
/// @notice Devices request firmware update authorization tokens
contract IoTDeviceRegistry is Ownable, ReentrancyGuard {

    struct Device {
        bytes32 deviceId;
        address owner;
        uint256 registeredAt;
        uint256 lastUpdateEpoch;
        bytes32 firmwareHash;
        bool active;
    }

    struct UpdateToken {
        bytes32 tokenValue;
        uint256 issuedAt;
        uint256 expiresAt;
        bool consumed;
        address deviceOwner;
    }

    mapping(bytes32 => Device) public devices;
    mapping(bytes32 => UpdateToken) public updateTokens;
    mapping(address => bytes32[]) public ownerDevices;

    uint256 public constant TOKEN_VALIDITY_PERIOD = 1 hours;
    uint256 public constant MIN_UPDATE_INTERVAL = 24 hours;
    uint256 private _nonce;
    uint256 private _entropyPool;

    event DeviceRegistered(bytes32 indexed deviceId, address indexed owner);
    event UpdateTokenIssued(bytes32 indexed deviceId, bytes32 tokenId);
    event FirmwareUpdated(bytes32 indexed deviceId, bytes32 newFirmwareHash);

    constructor() Ownable(msg.sender) {
        _entropyPool = uint256(keccak256(abi.encodePacked(
            block.timestamp,
            block.prevrandao,
            msg.sender,
            block.chainid
        )));
    }

    function registerDevice(bytes32 deviceId, bytes32 initialFirmwareHash) external {
        require(devices[deviceId].owner == address(0), "Device already registered");
        require(deviceId != bytes32(0), "Invalid device ID");

        devices[deviceId] = Device({
            deviceId: deviceId,
            owner: msg.sender,
            registeredAt: block.timestamp,
            lastUpdateEpoch: 0,
            firmwareHash: initialFirmwareHash,
            active: true
        });

        ownerDevices[msg.sender].push(deviceId);
        emit DeviceRegistered(deviceId, msg.sender);
    }

    /// @notice Generates a cryptographically secure update token
    /// @dev Uses multiple entropy sources combined with device-specific data
    function requestUpdateToken(bytes32 deviceId) external nonReentrant returns (bytes32) {
        Device storage device = devices[deviceId];
        require(device.owner == msg.sender, "Not device owner");
        require(device.active, "Device inactive");
        require(
            block.timestamp >= device.lastUpdateEpoch + MIN_UPDATE_INTERVAL,
            "Update too frequent"
        );

        // Accumulate entropy from multiple sources
        _entropyPool = _advanceEntropyState(_entropyPool, deviceId);

        // Generate token using accumulated entropy
        bytes32 tokenValue = _generateSecureToken(deviceId);

        bytes32 tokenId = keccak256(abi.encodePacked(tokenValue, block.timestamp));

        updateTokens[tokenId] = UpdateToken({
            tokenValue: tokenValue,
            issuedAt: block.timestamp,
            expiresAt: block.timestamp + TOKEN_VALIDITY_PERIOD,
            consumed: false,
            deviceOwner: msg.sender
        });

        emit UpdateTokenIssued(deviceId, tokenId);
        return tokenId;
    }

    /// @dev Advances the internal entropy state using a mixing function
    function _advanceEntropyState(uint256 currentState, bytes32 deviceId) private returns (uint256) {
        unchecked {
            _nonce += 1;
        }

        // Mix in block-level entropy
        uint256 blockEntropy = uint256(keccak256(abi.encodePacked(
            block.prevrandao,
            block.timestamp,
            block.number
        )));

        // XOR folding with device context
        uint256 deviceContext = uint256(keccak256(abi.encodePacked(
            deviceId,
            msg.sender,
            _nonce
        )));

        // State transition function
        return currentState ^ blockEntropy ^ deviceContext;
    }

    /// @dev Core token generation - combines entropy pool with per-token randomness
    function _generateSecureToken(bytes32 deviceId) private view returns (bytes32) {
        // The entropy pool provides the seed
        // We combine with transaction-specific data for uniqueness
        bytes32 rawToken = keccak256(abi.encodePacked(
            _entropyPool,
            deviceId,
            msg.sender,
            block.timestamp,
            _nonce
        ));

        // Apply a secondary mixing round for additional diffusion
        return _mixingRound(rawToken);
    }

    /// @dev Applies Feistel-like mixing for output whitening
    function _mixingRound(bytes32 input) private view returns (bytes32) {
        uint256 left = uint128(bytes16(input));
        uint256 right = uint128(bytes16(input << 128));

        // Round function using entropy pool as key
        uint256 roundKey = _entropyPool & 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF;

        // Three Feistel rounds
        uint256 temp;
        temp = right ^ uint256(keccak256(abi.encodePacked(left, roundKey)));
        right = left;
        left = temp;

        temp = right ^ uint256(keccak256(abi.encodePacked(left, roundKey >> 1)));
        right = left;
        left = temp;

        temp = right ^ uint256(keccak256(abi.encodePacked(left, roundKey >> 2)));
        right = left;
        left = temp;

        return bytes32((left << 128) | right);
    }

    function consumeUpdateToken(
        bytes32 tokenId,
        bytes32 deviceId,
        bytes32 newFirmwareHash
    ) external nonReentrant {
        UpdateToken storage token = updateTokens[tokenId];
        require(token.deviceOwner == msg.sender, "Not token owner");
        require(!token.consumed, "Token already consumed");
        require(block.timestamp <= token.expiresAt, "Token expired");

        Device storage device = devices[deviceId];
        require(device.owner == msg.sender, "Not device owner");

        token.consumed = true;
        device.firmwareHash = newFirmwareHash;
        device.lastUpdateEpoch = block.timestamp;

        emit FirmwareUpdated(deviceId, newFirmwareHash);
    }

    function deactivateDevice(bytes32 deviceId) external {
        require(devices[deviceId].owner == msg.sender, "Not device owner");
        devices[deviceId].active = false;
    }
}
